import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/SuffixArray.html","title":"SuffixArray","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.92,"words":575},"filePathRelative":"SuffixArray.md"}`),a={name:`SuffixArray.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="suffixarray" tabindex="-1"><a class="header-anchor" href="#suffixarray"><span>SuffixArray</span></a></h1><p><a href="./アルゴリズム.html">アルゴリズム</a>, <a href="./EnhancedSuffixArray.html">EnhancedSuffixArray</a>はSuffixArrayにlcpテーブルや追加のテーブルを持たせてSuffix Treeと同様の能力を与えたもの</p><ul><li><a href="https://en.wikipedia.org/wiki/Suffix_array" target="_blank" rel="noopener noreferrer">Suffix array - Wikipedia</a></li><li><a href="https://arxiv.org/abs/1101.3448" target="_blank" rel="noopener noreferrer">1101.3448 Inducing the LCP-Array</a> SA-ISのついでにLCPテーブルも構築するもの</li></ul><h2 id="sa-is" tabindex="-1"><a class="header-anchor" href="#sa-is"><span>SA-IS</span></a></h2><p>以下の論文のアルゴリズムの略称。<a href="./論文.html">論文</a></p><p><a href="https://ieeexplore.ieee.org/document/4976463" target="_blank" rel="noopener noreferrer">Linear Suffix Array Construction by Almost Pure Induced-Sorting - IEEE Conference Publication - IEEE Xplore</a></p><p>線形時間で作れてアルゴリズムもめちゃ短い。たくさん解説がある。</p><p><a href="https://trap.jp/post/953/" target="_blank" rel="noopener noreferrer">SA-ISで高速にSuffix Arrayを構築する話【新歓ブログリレー 38日目】 - 東京科学大学デジタル創作同好会traP</a> は例がある程度分かりやすい。</p><p><a href="https://shogo82148.github.io/homepage/memo/algorithm/suffix-array/sa-is.html?ref=trap.jp" target="_blank" rel="noopener noreferrer">SA-IS - Shogo Computing Laboratory</a> こちらは自然とソートされるメカニズムの解説が詳しい。</p><h3 id="s-typeとl-type" tabindex="-1"><a class="header-anchor" href="#s-typeとl-type"><span>S-typeとL-type</span></a></h3><ul><li>S-type: i番目からのサフィックス ＜ i+1番目からのサフィックス</li><li>L-type: i番目からのサフィックス ＞ i+1番目からのサフィックス</li></ul><p>一番最後の文字はS-typeと約束。</p><p><img src="/RandomThoughts/assets/0001-v03_MI8K.png" alt="imgs/SuffixArray/0001.png"></p><h3 id="lms" tabindex="-1"><a class="header-anchor" href="#lms"><span>LMS</span></a></h3><p>iがS-typeでi-1がL-typeのiをLeft Most S-type, 略してLMSと言う。 また、この時 <code>S[i]</code> をLMS characterという。</p><h3 id="lms-substring" tabindex="-1"><a class="header-anchor" href="#lms-substring"><span>LMS-substring</span></a></h3><p>iとjがLMSで、間がLMS characterで無い時、Si..jをLMS-substringと言う。</p><h3 id="アルゴリズムの概要-2のコード" tabindex="-1"><a class="header-anchor" href="#アルゴリズムの概要-2のコード"><span>アルゴリズムの概要（2のコード）</span></a></h3><p>ポイントとしては、帰納的に、後ろから考える事。つまりCが成り立っていればDが成り立つ、を、「Cをどうやるかは置いといて」まずは理解する。 そしてこれを遡って最終的にAを考える、という順番になる。</p><p>それを踏まえて以下でSA-ISの概要をまとめると</p><ul><li>LMS Substringをソートする(2.4)</li><li>ソートされた順番のindexを名前としてSを置き換えてS1にして、小さいS1についてSA-ISを再帰的に実行 <ul><li>一番小さい時にSAを求める（これは単なるバケットソート）</li></ul></li><li>SA1からSAを求める (2.3)</li></ul><p>となる。 最初に必要になるLMS Substringのソートが論文では最後にでてくるので読み方に注意が必要。</p><h3 id="induced-sort" tabindex="-1"><a class="header-anchor" href="#induced-sort"><span>Induced Sort</span></a></h3><p>それぞれの手順で、Induced Sortというのが使われる。 これはバケットに従ってソートされた何かが入っている状態から始めて、その左隣を見てはバケットに順番に入れていくと自動的にソートされる、 というもの。アルファベットのバケットをイメージしつつ読んでいくと良い。</p><p>基本的な手順は以下になっている。</p><ul><li>ソートされたLMSが入っている（帰納的に考える！）</li><li>入っているものを順番に見ていって一文字左がLなら入れていく <ul><li>ここまで見たものよりもLなので必ず今見ている所より後ろに入る</li></ul></li><li>入っているものを逆順に見ていって一文字左がSなら入れていく</li></ul><p>これで最終的にはLもSも全部ソートされた状態になる、というのがIndueced Sort。</p><p>これは、後述するSA1からSAを作る時も、LMS Substringをソートする時にも使われる。</p><p><a href="https://shogo82148.github.io/homepage/memo/algorithm/suffix-array/two-stage.html" target="_blank" rel="noopener noreferrer">2段階ソート - Shogo Computing Laboratory</a>の解説も参照の事。</p><h3 id="lms-substringの名前づけ" tabindex="-1"><a class="header-anchor" href="#lms-substringの名前づけ"><span>LMS Substringの名前づけ</span></a></h3><p>LMS Substringが順番にソート出来ているとする。この順番を表すint値でLMS Substringを置き換えたもの（S1）はSより短くなる。 そしてこのS1のSuffix Arrayが求まると、ここからSのSuffix Arrayを求める事が出来る。（2.3 Inducing SA from SA1）</p><p>このソート「されているとする」というのがポイントで、ソートの問題は後ででてくるので、 説明を読む時は「ソートがされているとするなら」という気分で読んでいく必要がある。</p><p>このソートの順番での置き換えは記号が分かりにくいのも読みづらくしていると思う。</p><p>ソートがされているとするならその順番で置き換えたS1のSuffix Arrayを求める問題と、そのSA1からSAを求める問題に分ける事が出来る。</p><p>置き換えたS1のSuffix Arrayを求める問題は、再帰的に小さくしていけば、最終的には先頭の文字のバケットソートでソート出来る所に行き着く。</p><h3 id="_2-3-sa1からsaを作る" tabindex="-1"><a class="header-anchor" href="#_2-3-sa1からsaを作る"><span>2.3 SA1からSAを作る</span></a></h3><p>これもInduced Sortで作れる。SA1がバケットに正しく入っている前提でL-typeを入れていって、後ろからS-typeを入れていく。</p><h3 id="_2-4-lms-substringのソートにもinduced-sortを使う" tabindex="-1"><a class="header-anchor" href="#_2-4-lms-substringのソートにもinduced-sortを使う"><span>2.4 LMS SubstringのソートにもInduced Sortを使う</span></a></h3><p>2.4に、LMS SubstringのソートにもInduced Sortを使う、という話がある。</p><p>LMS-prefixというものを定義して考える。 これはあるiから最初のS-typeまでのsubstring。 これを使う事でInduced Sortの1文字から始めて伸ばしていく事を可能にしている。</p><p>LMS-prefixが1文字のS-typeから始めて左に伸ばしてInduced sortしていくと、 最終的に2文字以上のLMS-prefixは正しくソートされる、という事を示せる。</p><p>これは2文字以上のS-typeから始まる全部分文字列もソートされる事を意味し、LMS-substringもそれに含まれる。</p><p>prefix側の1文字目から始めて増やしていく、というのがポイント。</p>`,43)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};